import { categoryMapping } from '../../utils/applicationTypes';
const categories = Object.keys(categoryMapping);

export default function HRMDynamicFormRenderer({ onSubmit }) {
  const [selectedCategory, setSelectedCategory] = useState("");
  const [requestType, setRequestType] = useState("");
  const [formData, setFormData] = useState({});
  const [contextData, setContextData] = useState(null);
  const [loadingContext, setLoadingContext] = useState(false);

  // Reset requestType when category changes
  useEffect(() => {
    setRequestType("");
    setFormData({});
    setContextData(null);
  }, [selectedCategory]);

  // Reset form when request type changes
  useEffect(() => {
    setFormData({});
    if (requestType) {
      fetchContextData(requestType);
    } else {
      setContextData(null);
    }
  }, [requestType]);

  const fetchContextData = async (type) => {
    setLoadingContext(true);
    try {
      const res = await fetch(`${API_URL}/hrm/member/application-context?type=${encodeURIComponent(type)}`, {
        headers: {
          'Authorization': `Bearer ${authToken()}`,
          'Accept': 'application/json'
        }
      });
      const json = await res.json();
      if (json.success) {
        setContextData(json.data.metrics);
      }
    } catch (err) {
      console.error("Failed to fetch context", err);
    } finally {
      setLoadingContext(false);
    }
  };

  const rawFields = formConfigs[requestType] || [];
  // Filter out any existing comments or attachment fields from the hardcoded config to prevent duplication
  const filteredFields = rawFields.filter(f => f.type !== 'attachment' && f.id !== 'comments' && f.id !== 'details');

  const fields = requestType ? [
    { id: "subject", type: "text", label: "Subject", required: true },
    ...filteredFields,
    { id: "comments", type: "richtext", label: "Comments / Additional Notes", required: false },
    { id: "global_attachment", type: "attachment", label: "Supporting Documents (Optional)", required: false }
  ] : [];

  const handleFieldChange = (id, value) => {
    setFormData(prev => ({ ...prev, [id]: value }));
  };

  const handleSubmit = () => {
    // Basic validation
    const missing = fields.filter(f => f.required && (!formData[f.id] || (Array.isArray(formData[f.id]) && formData[f.id].length === 0)));
    if (missing.length > 0) {
      alert(`Please fill all required fields: ${missing.map(m => m.label).join(", ")}`);
      return;
    }
    if (onSubmit) {
      onSubmit({ requestType, data: formData });
    }
  };

  const getIcon = (iconName) => {
    switch (iconName) {
      case 'calendar': return <Calendar size={18} />;
      case 'check-circle': return <CheckCircle2 size={18} />;
      case 'alert-circle': return <AlertCircle size={18} />;
      case 'banknote': return <Banknote size={18} />;
      case 'pie-chart': return <PieChart size={18} />;
      case 'file-text': return <FileText size={18} />;
      case 'briefcase': return <Briefcase size={18} />;
      case 'building': return <Building size={18} />;
      case 'clock': return <Clock size={18} />;
      default: return <FileText size={18} />;
    }
  };

  const renderContextDashboard = () => {
    if (loadingContext) {
      return <div className="hrm-context-dashboard loading"><div className="spinner"></div> Loading application context...</div>;
    }
    if (!contextData || contextData.length === 0) return null;

    return (
      <div className="hrm-context-dashboard">
        <h4 className="hrm-context-title">Your {requestType} Overview</h4>
        <div className="hrm-context-grid">
          {contextData.map((metric, idx) => (
            <div key={idx} className="hrm-context-card">
              <div className="hrm-context-icon">
                {getIcon(metric.icon)}
              </div>
              <div className="hrm-context-info">
                <span className="hrm-context-label">{metric.label}</span>
                <span className="hrm-context-value">{metric.value}</span>
                {metric.subtext && <span className="hrm-context-subtext">{metric.subtext}</span>}
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  const dependentTypes = selectedCategory ? categoryMapping[selectedCategory] : [];

  return (
    <div className="hrm-dynamic-form-container">
      <div className="hrm-dynamic-form-fill">
          <div className="hrm-form-section" style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginBottom: '24px' }}>
            <div>
              <label className="hrm-dynamic-label">Application Category</label>
              <select 
                className="hrm-dynamic-select"
                value={selectedCategory} 
                onChange={(e) => setSelectedCategory(e.target.value)}
              >
                <option value="">-- Select Category --</option>
                {categories.map(c => (
                  <option key={c} value={c}>{c}</option>
                ))}
              </select>
            </div>

            {selectedCategory && (
              <div>
                <label className="hrm-dynamic-label">Request Type</label>
                <select 
                  className="hrm-dynamic-select"
                  value={requestType} 
                  onChange={(e) => setRequestType(e.target.value)}
                >
                  <option value="">-- Choose Request Type --</option>
                  {dependentTypes.map(t => (
                    <option key={t} value={t}>{t}</option>
                  ))}
                </select>
              </div>
            )}
          </div>

          {requestType && (
            <div className="hrm-form-fields" style={{ borderTop: '1px solid var(--border-light)', paddingTop: '24px' }}>
              <h3 className="hrm-dynamic-title"><ClipboardList size={22} className="text-pms-primary" /> {requestType} Details</h3>
              {renderContextDashboard()}
              <div className="hrm-fields-grid">
                {fields.map(field => (
                  <div key={field.id} className="hrm-field-wrapper" style={{ gridColumn: field.type === 'richtext' ? '1 / -1' : 'auto' }}>
                    <HRMFieldRenderer 
                      field={field} 
                      value={formData[field.id]} 
                      onChange={(val) => handleFieldChange(field.id, val)} 
                    />
                  </div>
                ))}
              </div>
              <div className="hrm-form-actions">
                <button type="button" className="hrm-btn hrm-btn-primary" onClick={handleSubmit}>
                  Submit Request <Send size={18} />
                </button>
              </div>
            </div>
          )}
      </div>
    </div>
  );
}

import React from "react";
import HRMDatePicker from "./HRMDatePicker";
import HRMTimePicker from "./HRMTimePicker";
import HRMDateTimePicker from "./HRMDateTimePicker";
import HRMDateRangePicker from "./HRMDateRangePicker";
import HRMRichTextEditor from "./HRMRichTextEditor";
import HRMAttachmentUploader from "./HRMAttachmentUploader";

export default function HRMFieldRenderer({ field, value, onChange }) {
  const { type, label, required, options } = field;

  switch (type) {
    case "date":
      return <HRMDatePicker label={label} value={value} onChange={onChange} required={required} onClear={() => onChange("")} />;
    case "time":
      return <HRMTimePicker label={label} value={value} onChange={onChange} required={required} onClear={() => onChange("")} />;
    case "datetime":
      return <HRMDateTimePicker label={label} value={value} onChange={onChange} required={required} onClear={() => onChange("")} />;
    case "daterange":
      return <HRMDateRangePicker label={label} value={value} onChange={onChange} required={required} onClear={() => onChange({ start: "", end: "" })} />;
    case "dropdown":
      return (
        <div className="hrm-picker-container">
          {label && <label className="hrm-picker-label">{label} {required && <span className="req">*</span>}</label>}
          <select 
            className="hrm-picker-input" 
            style={{ border: '1px solid #cbd5e1', borderRadius: '8px', padding: '10px 12px' }} 
            value={value || ""} 
            onChange={(e) => onChange(e.target.value)} 
            required={required}
          >
            <option value="">Select...</option>
            {options?.map((opt, i) => (
              <option key={i} value={opt.value || opt}>{opt.label || opt}</option>
            ))}
          </select>
        </div>
      );
    case "amount":
    case "number":
      return (
        <div className="hrm-picker-container">
          {label && <label className="hrm-picker-label">{label} {required && <span className="req">*</span>}</label>}
          <input 
            type="number" 
            className="hrm-picker-input" 
            style={{ border: '1px solid #cbd5e1', borderRadius: '8px', padding: '10px 12px' }} 
            value={value || ""} 
            onChange={(e) => onChange(e.target.value)} 
            required={required}
            placeholder={type === "amount" ? "0.00" : ""}
          />
        </div>
      );
    case "text":
      return (
        <div className="hrm-picker-container">
          {label && <label className="hrm-picker-label">{label} {required && <span className="req">*</span>}</label>}
          <input 
            type="text" 
            className="hrm-picker-input" 
            style={{ border: '1px solid #cbd5e1', borderRadius: '8px', padding: '10px 12px' }} 
            value={value || ""} 
            onChange={(e) => onChange(e.target.value)} 
            required={required}
          />
        </div>
      );
    case "richtext":
      return <HRMRichTextEditor label={label} value={value} onChange={onChange} required={required} />;
    case "attachment":
      return <HRMAttachmentUploader label={label} files={value} onChange={onChange} required={required} />;
    default:
      return <div>Unsupported field type: {type}</div>;
  }
}

import React, { useRef, useEffect } from "react";
import { Bold, Italic, Underline, List, ListOrdered, AlignLeft, AlignCenter, AlignRight } from "lucide-react";
import "./HRMRichTextEditor.css";

export default function HRMRichTextEditor({ label, value, onChange, required }) {
  const editorRef = useRef(null);

  useEffect(() => {
    if (editorRef.current && value !== editorRef.current.innerHTML) {
      editorRef.current.innerHTML = value || "";
    }
  }, [value]);

  const execCmd = (cmd, arg = null) => {
    document.execCommand(cmd, false, arg);
    editorRef.current.focus();
    handleChange();
  };

  const handleChange = () => {
    if (onChange && editorRef.current) {
      onChange(editorRef.current.innerHTML);
    }
  };

  return (
    <div className="hrm-rt-container">
      {label && <label className="hrm-rt-label">{label} {required && <span className="req">*</span>}</label>}
      <div className="hrm-rt-wrapper">
        <div className="hrm-rt-toolbar">
          <button type="button" onClick={() => execCmd("bold")} title="Bold"><Bold size={14} /></button>
          <button type="button" onClick={() => execCmd("italic")} title="Italic"><Italic size={14} /></button>
          <button type="button" onClick={() => execCmd("underline")} title="Underline"><Underline size={14} /></button>
          <div className="hrm-rt-divider"></div>
          <button type="button" onClick={() => execCmd("insertUnorderedList")} title="Bullet List"><List size={14} /></button>
          <button type="button" onClick={() => execCmd("insertOrderedList")} title="Numbered List"><ListOrdered size={14} /></button>
          <div className="hrm-rt-divider"></div>
          <button type="button" onClick={() => execCmd("justifyLeft")} title="Align Left"><AlignLeft size={14} /></button>
          <button type="button" onClick={() => execCmd("justifyCenter")} title="Align Center"><AlignCenter size={14} /></button>
          <button type="button" onClick={() => execCmd("justifyRight")} title="Align Right"><AlignRight size={14} /></button>
        </div>
        <div
          ref={editorRef}
          className="hrm-rt-editor"
          contentEditable
          onInput={handleChange}
          onBlur={handleChange}
          role="textbox"
          aria-multiline="true"
        ></div>
      </div>
    </div>
  );
}

import React from "react";
import { Check, Clock, Eye, AlertCircle, RefreshCw } from "lucide-react";
import "./HRMStatusTimeline.css";

export default function HRMStatusTimeline({ status }) {
  // Define steps
  const steps = [
    { label: "Submitted", activeStatus: ["pending", "under review", "approved", "rejected", "returned"] },
    { label: "Under Review", activeStatus: ["under review", "approved", "rejected", "returned"] },
    { label: "Final Decision", activeStatus: ["approved", "rejected", "returned"] }
  ];

  const currentStatus = (status || "pending").toLowerCase();

  const getStepIcon = (label, isActive, isLast) => {
    if (!isActive) return <Clock size={14} />;
    if (isLast) {
      if (currentStatus === "approved") return <Check size={14} />;
      if (currentStatus === "rejected") return <AlertCircle size={14} />;
      if (currentStatus === "returned") return <RefreshCw size={14} />;
      return <Eye size={14} />;
    }
    return <Check size={14} />;
  };

  const getStepClass = (label, isActive, isLast) => {
    if (!isActive) return "hrm-tl-step";
    if (isLast) {
      if (currentStatus === "approved") return "hrm-tl-step hrm-tl-step-approved";
      if (currentStatus === "rejected") return "hrm-tl-step hrm-tl-step-rejected";
      if (currentStatus === "returned") return "hrm-tl-step hrm-tl-step-returned";
      return "hrm-tl-step hrm-tl-step-active";
    }
    return "hrm-tl-step hrm-tl-step-completed";
  };

  return (
    <div className="hrm-timeline-container">
      <h3 className="hrm-timeline-title">Status Timeline</h3>
      <div className="hrm-timeline">
        {steps.map((step, index) => {
          const isActive = step.activeStatus.includes(currentStatus);
          const isLast = index === steps.length - 1 || (!steps[index+1].activeStatus.includes(currentStatus));
          return (
            <div key={index} className={getStepClass(step.label, isActive, isLast)}>
              <div className="hrm-tl-icon-wrap">
                <div className="hrm-tl-icon">{getStepIcon(step.label, isActive, isLast)}</div>
                {index < steps.length - 1 && <div className="hrm-tl-line"></div>}
              </div>
              <div className="hrm-tl-content">
                <div className="hrm-tl-label">{step.label}</div>
                {isLast && isActive && (
                  <div className="hrm-tl-status-text">
                    Current Status: <strong style={{ textTransform: 'capitalize' }}>{currentStatus}</strong>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

