                      <td style={{ padding: "12px", textAlign: "right" }}>
                        <button
                          style={{
                            padding: "4px 10px",
                            fontSize: "11px",
                            fontWeight: "700",
                            background: "#0082ff",
                            color: "#fff",
                            border: "none",
                            borderRadius: "6px",
                            cursor: "pointer",
