                  <div
                    key={g.id}
                    style={{
                      background: "#f8fafc",
                      border: "1px solid #e2e8f0",
                      borderRadius: "10px",
                      padding: "16px",
                    }}
                  >
                    <div
                      style={{
                        display: "flex",
                        justify: "space-between",
                        alignItems: "center",
                        marginBottom: "8px",
                      }}
                    >
                      <span
                        style={{
                          padding: "3px 8px",
                          borderRadius: "4px",
                          fontSize: "11px",
                          fontWeight: "700",
                          background: "#eff6ff",
                          color: "#1d4ed8",
                        }}
                      >
                        {g.category}
                      </span>

                      <span
                        style={{
                          fontSize: "11px",
                          fontWeight: "700",
                          color: g.status === "Completed" ? "#166534" : "#b45309",
                        }}
                      >
                        {g.status}
                      </span>
                    </div>

                    <h3 style={{ margin: "0 0 6px", fontSize: "15px", color: "#0f172a" }}>
                      {g.goal_title}
                    </h3>
                    <p style={{ margin: "0 0 10px", fontSize: "12px", color: "#64748b" }}>
