                    <div style={{ marginBottom: "8px" }}>
                      <div
                        style={{
                          display: "flex",
                          justify: "space-between",
                          fontSize: "11px",
                          color: "#475569",
                          marginBottom: "4px",
                        }}
                      >
                        <span>Progress: {pct}%</span>
                        <strong>
                          {g.current_value} / {g.target_value} {g.unit}
                        </strong>
                      </div>

                      <div
                        style={{
                          width: "100%",
                          background: "#e2e8f0",
                          height: "8px",
                          borderRadius: "4px",
                          overflow: "hidden",
                        }}
                      >
                        <div
                          style={{
                            width: `${pct}%`,
                            background: g.status === "Completed" ? "#16a34a" : "#0082ff",
