                      </div>
                    </div>

                    <div
                      style={{
                        fontSize: "11px",
                        color: "#94a3b8",
                        display: "flex",
                        justify: "space-between",
                        alignItems: "center",
                        marginTop: "10px",
                      }}
                    >
                      <span>Weightage: {g.weightage}%</span>
                      <button
                        style={{
                          padding: "3px 8px",
                          fontSize: "11px",
                          fontWeight: "700",
                          background: "#eff6ff",
                          color: "#1d4ed8",
                          border: "1px solid #bfdbfe",
                          borderRadius: "4px",
                          cursor: "pointer",
                          display: "flex",
                          alignItems: "center",
                          gap: "4px",
                        }}
                        onClick={() => {
                          setActiveGoalToUpdate(g);
                          setUpdateGoalValue(g.current_value);
                          setUpdateGoalStatus(g.status);
                          setUpdateGoalModalOpen(true);
                        }}
                      >
                        <Edit3 size={14} /> Update Progress
                      </button>
                    </div>
                  </div>
                );
              })}
              {goals.length === 0 && (
                <div
                  style={{
                    gridColumn: "1 / -1",
                    textAlign: "center",
                    padding: "32px",
                    color: "#94a3b8",
                  }}
                >
                  No active goals assigned yet. Click "Assign New Goal" above to create one.
                </div>
              )}
            </div>
          </section>
        )}

        {/* TAB 3: 360-DEGREE APPRAISALS */}
