                >
                  <div
                    style={{
                      display: "flex",
                      justify: "space-between",
                      fontSize: "13px",
                      fontWeight: "700",
                      marginBottom: "8px",
                      color: skill.color,
                    }}
                  >
                    <span>{skill.label}</span>
                    <span>{skill.score} / 5.0</span>
                  </div>

                  <div
                    style={{
                      width: "100%",
                      background: "#e2e8f0",
                      height: "8px",
                      borderRadius: "4px",
                      overflow: "hidden",
                    }}
                  >
                    <div
                      style={{
                        width: `${(skill.score / 5.0) * 100}%`,
                        background: skill.color,
                        height: "100%",
                        borderRadius: "4px",
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* TAB 5: TOP PERFORMER LEADERBOARD */}
        {activeTab === "top" && (
          <section className="att-card">
