                  <button type="button" className="att-btn" style={{ background: "#f1f5f9", color: "#334155" }} onClick={() => setUpdateGoalModalOpen(false)}>Cancel</button>
                  <button type="submit" className="att-btn att-btn--primary">Save Progress</button>
                </div>
              </form>
            </div>
          </div>
        )}

